update project_cost_assumptions set note = 'IPOできる大量生産の状態を前提に、売上10,000,000,000円に届く量で置いた（2026-09-14 まさ「この計算はIPOできるレベルの大量生産状態を前提にしたいので、売上100億到達レベルを前提にしたパラメータにして」）。売上 ＝ 年間処理量 × 想定売上単価（いまは500円/m³）＝ 10,000,000,000円/年。顧客1社あたり年30,000m³（100m³/日 × 300日）なら約667社分。菌体の製造拠点で年に作る量は、この量 × 使い切る菌体量 ÷ 販売率 で計算する（入力ではない）。用途ごとに、その用途だけでこの量を処理したときとして出す。売価を変えると売上も変わるので、売上10,000,000,000円に合わせるときはこの量も変える。', updated_at = now() where cost_assumption_id = 'ca6_business_annual_volume' and cost_model_id = 'cm_p21_260820';
