update project_cost_items set note = 'カートリッジ群6,000,000円（恒久設備）の内訳。内部の菌体保持モジュールのみ交換するため、ここには交換費を含まない。各項目の金額は今後個別に確定させ、確定後は親行を子行の合計に切替える。耐用年数10年は仮置きで要メーカー確認。', updated_at = now() where cost_item_id = 'ci_260820_068' and cost_model_id = 'cm_p21_260820';
